// The prereqs status band (ADR 2026-027): a Claude Code plugin that draws
// bounded/prereqs's status above the prompt, from the status file bounded's
// own hook writes after each finished tool call and agent run
// (.bounded/prereqs/status.json, ADR 2026-026). It decides nothing and holds
// no phase: it keeps one value, when it last saw a finish, so it never shows
// a reading older than that as current. Every hook has a .catch: a band that
// fails never changes or blocks an event, and draws "unavailable", never a
// stale status. Every use of $ is in this file (the engine allows $ to be
// passed only to functions declared here); the modules it imports are pure.
import type { AbovePromptFields, BandEngine, On } from "./engine-subset";
import { drawFailedLines, missingFileLines, otherProjectLines, READING_WAIT_MS, statusLines, unreadableLines } from "./prereqs-status-band-lines";
import { readStatusFile, STATUS_FILE } from "./prereqs-status-file";
import { PROJECT_CONFIG_NAMES } from "./project-config-names";

/** The band's one value: when it last saw a finished tool call or agent run, from $.clock.now(). */
const LAST_FINISH_SEEN_AT = { plugin: "bounded-prereqs-status-band", key: "lastFinishSeenAt" } as const;
/** How often the band draws itself again, so "updating" turns into "unavailable" and a late file is found. */
const REDRAW_EVERY_MS = 2_000;
/** How many times a mark is tried when another finish's mark lands in between. */
const MARK_ATTEMPTS = 5;

/** Whether this environment's redraw timer runs: it dies with the environment (a reload), and so does this. */
let redrawing = false;

/** Starts the 2-second redraw, once per environment. */
function startRedraw<Element>($: BandEngine<Element>): void {
  if (redrawing) return;
  redrawing = true;
  $.clock.every(REDRAW_EVERY_MS, () => $.ui.invalidate("ui.render"));
}

/**
 * Marks a finish: the mark only moves forward. The time is read once; the
 * mark is written only while it stands at the version read, and read again
 * when another write landed first, so two finishes whose writes land out of
 * order leave the later time.
 */
async function markFinish<Element>($: BandEngine<Element>): Promise<void> {
  const now = await $.clock.now();
  for (let attempt = 0; attempt < MARK_ATTEMPTS; attempt += 1) {
    const held = await $.state.get(LAST_FINISH_SEEN_AT);
    if (typeof held.value === "number" && held.value >= now) return;
    const written = await $.state.set(LAST_FINISH_SEEN_AT, now, { ifVersion: held.version });
    if (written.isSet) break;
  }
  // Drawn again the moment the wait for its reading ends, so "updating" turns into "unavailable" then, not at the next 2-second redraw.
  $.clock.after(READING_WAIT_MS + 1, () => $.ui.invalidate("ui.render"));
}

/** Where `path` lands, every link resolved; undefined when it leads nowhere. */
async function realPathOf<Element>($: BandEngine<Element>, path: string): Promise<string | undefined> {
  try {
    return (await $.fs.stat(path, { resolve: true })).realPath;
  } catch {
    return undefined;
  }
}

/** Whether the session's root holds a bounded configuration. */
async function hasConfig<Element>($: BandEngine<Element>, root: string): Promise<boolean> {
  for (const name of PROJECT_CONFIG_NAMES) if (await $.fs.exists(`${root}/${name}`)) return true;
  return false;
}

/** The band's lines for the project at `root`: the status file read, refused, or not there. */
async function linesFor<Element>($: BandEngine<Element>, root: string): Promise<string[]> {
  const path = `${root}/${STATUS_FILE}`;
  if (!(await $.fs.exists(path))) return missingFileLines();
  let text: string;
  try {
    text = await $.fs.read(path);
  } catch (thrown) {
    return unreadableLines(thrown instanceof Error ? thrown.message : String(thrown));
  }
  const reading = readStatusFile(text);
  if (reading.ok) {
    const sessionRoot = await realPathOf($, root);
    const projectRoot = await realPathOf($, reading.value.projectRoot);
    if (sessionRoot === undefined || projectRoot === undefined || sessionRoot !== projectRoot) return otherProjectLines(reading.value.projectRoot, root);
  }
  const held = await $.state.get(LAST_FINISH_SEEN_AT);
  return statusLines(reading, { lastFinishSeenAt: held.value, now: await $.clock.now() });
}

/** The band's tree: one truncated line of text per line. */
function draw<Element>($: BandEngine<Element>, e: AbovePromptFields, lines: readonly string[]): Element {
  const { Box, Text } = $.ui.resolve(e);
  return Box({ flexDirection: "column", children: lines.map((line) => Text({ wrap: "truncate-end", children: line })) });
}

export function register(on: On): void {
  on("session.start", async ($, e, next) => {
    startRedraw($);
    return next(e);
  }).catch((_$, e, next) => next(e));

  on("classic.PostToolUse", async ($, e, next) => {
    startRedraw($);
    await markFinish($);
    const answer = await next(e);
    $.ui.invalidate("ui.render");
    return answer;
  }).catch((_$, e, next) => next(e));

  on("classic.PostToolUseFailure", async ($, e, next) => {
    startRedraw($);
    await markFinish($);
    const answer = await next(e);
    $.ui.invalidate("ui.render");
    return answer;
  }).catch((_$, e, next) => next(e));

  // A finish with an empty agent_type names no agent a rule can require, and bounded's hook records nothing for it.
  on("classic.SubagentStop", async ($, e, next) => {
    startRedraw($);
    if (e.agent_type !== "") await markFinish($);
    const answer = await next(e);
    $.ui.invalidate("ui.render");
    return answer;
  }).catch((_$, e, next) => next(e));

  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e);
    const root = await $.session.root();
    if (!(await hasConfig($, root))) return next(e);
    return draw($, e, await linesFor($, root));
  }).catch(($, e, next) => {
    try {
      return draw($, e, drawFailedLines(next.error.message ?? next.error.kind));
    } catch {
      return undefined;
    }
  });
}

files.hooks/engine-subset.ts:
// The part of Claude Code's plugin API the band uses, typed by hand (ADR
// 2026-027), so the workspace's own tsc checks the band without the engine's
// declarations, which Claude Code lays only beside a plugin it loads.
// tests/register.typecheck.ts assigns the band's register to the engine's
// Register, so tsc against those declarations proves this subset is the
// engine's (bun run check:prereqs-status-band). Every member is a
// function-typed property, so it is checked strictly. Hooks are generic in
// the event, the chain's answer and the element type, so each takes the
// engine's own types when the engine calls it. Types only.

/** The surfaces that draw a component. */
export type Surface = "terminal" | "desktop" | "mobile" | "vscode";

/** The band's one value in $.state: when it last saw a finished tool call or agent run (ADR 2026-027). */
export type LastFinishSeenAtRef = { readonly plugin: "bounded-prereqs-status-band"; readonly key: "lastFinishSeenAt" };

/** The two elements the band draws with, from a surface's table. */
export interface BandElements<Element> {
  readonly Box: (props: { flexDirection: "column"; children: Element[] }) => Element;
  readonly Text: (props: { wrap: "truncate-end"; children: string }) => Element;
}

/** The calls on $ the band makes. */
export interface BandEngine<Element> {
  readonly session: {
    /** The session's project root, absolute. */
    readonly root: () => Promise<string>;
  };
  readonly fs: {
    readonly exists: (path: string) => Promise<boolean>;
    /** Rejects when the file is missing or cannot be read. */
    readonly read: (path: string) => Promise<string>;
    /** With `resolve`, `realPath` too: where the path lands. Rejects when missing. */
    readonly stat: (path: string, options: { resolve: boolean }) => Promise<{ readonly realPath?: string | undefined }>;
  };
  readonly state: {
    readonly get: (ref: LastFinishSeenAtRef) => Promise<{ readonly value: number | null | undefined; readonly version: number }>;
    readonly set: (ref: LastFinishSeenAtRef, value: number | null, options: { ifVersion: number }) => Promise<{ readonly isSet: boolean; readonly version: number }>;
  };
  readonly clock: {
    /** Milliseconds since the epoch. */
    readonly now: () => Promise<number>;
    /** Calls `fn` once after `ms` milliseconds, unless the module reloads first. */
    readonly after: (ms: number, fn: () => void) => unknown;
    /** Calls `fn` every `ms` milliseconds until the module reloads. */
    readonly every: (ms: number, fn: () => void) => unknown;
  };
  readonly ui: {
    readonly invalidate: (event: "ui.render") => void;
    readonly resolve: (e: { readonly surface: Surface; readonly component: "AbovePrompt" }) => BandElements<Element>;
  };
}

/** `next` in a hook: the rest of the chain, resolving to its answer. */
export type Next<E, Answer> = (e: E) => Promise<Answer>;

/** A hook on a classic hook event or session.start, which passes the chain's answer through. */
export type PassingHook<Fields> = <E extends Fields, Answer, Element>($: BandEngine<Element>, e: E, next: Next<E, Answer>) => Promise<Answer>;

/** What `next` carries into a `.catch` handler: why the hook failed. */
export interface Caught {
  readonly error: { readonly kind: string; readonly message?: string | undefined };
}

/** The handler a registration's `.catch` sets: here, the chain's answer, run once. */
export type PassingCatch<Fields> = <E extends Fields, Answer, Element>($: BandEngine<Element>, e: E, next: Next<E, Answer> & Caught) => Promise<Answer>;

/** The band above the prompt, as its ui.render hook receives it. */
export interface AbovePromptFields {
  readonly surface: Surface;
  readonly component: "AbovePrompt";
  readonly props: { readonly hasSurvey: boolean };
}

/** The ui.render hook on AbovePrompt: a tree, or the engine's own (`next`). */
export type RenderHook = <E extends AbovePromptFields, Answer, Element>($: BandEngine<Element>, e: E, next: Next<E, Answer>) => Promise<Element | Answer>;

/** The ui.render hook's `.catch`: a tree saying the band could not draw, or undefined for the engine's own. */
export type RenderCatch = <E extends AbovePromptFields, Answer, Element>($: BandEngine<Element>, e: E, next: Next<E, Answer> & Caught) => Element | undefined;

/** What `on` answers: the registration, whose `.catch` sets the handler run when the hook throws. */
export interface Registration<Handler> {
  readonly catch: (handler: Handler) => void;
}

/** A SubagentStop: the agent type it carries may be empty. */
export interface SubagentStopFields {
  readonly agent_type: string;
}

/** `on`, for the events the band hooks. */
export interface On {
  (event: "session.start", hook: PassingHook<object>): Registration<PassingCatch<object>>;
  (event: "classic.PostToolUse", hook: PassingHook<object>): Registration<PassingCatch<object>>;
  (event: "classic.PostToolUseFailure", hook: PassingHook<object>): Registration<PassingCatch<object>>;
  (event: "classic.SubagentStop", hook: PassingHook<SubagentStopFields>): Registration<PassingCatch<SubagentStopFields>>;
  (event: "ui.render", matcher: { readonly component: "AbovePrompt" }, hook: RenderHook): Registration<RenderCatch>;
}

